const crypto = require('crypto');
const ALPHA = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

function b58encode(buf) {
  // count leading zeros
  let nPad = 0;
  while (nPad < buf.length && buf[nPad] === 0) nPad++;
  let n = 0n;
  for (const b of buf) n = n * 256n + BigInt(b);
  let out = '';
  while (n > 0n) {
    const r = n % 58n;
    n = n / 58n;
    out = ALPHA[Number(r)] + out;
  }
  return '1'.repeat(nPad) + (out === '' ? (buf.length ? '' : '') : out) || ('1'.repeat(nPad));
}

// careful reimplementation matching python base58 b58encode
function b58encode2(buf) {
  let nPad = 0;
  while (nPad < buf.length && buf[nPad] === 0) nPad++;
  let n = 0n;
  for (const b of buf) n = n * 256n + BigInt(b);
  let out = '';
  while (n > 0n) {
    out = ALPHA[Number(n % 58n)] + out;
    n = n / 58n;
  }
  return '1'.repeat(nPad) + out;
}

function b58decode(s) {
  if (Buffer.isBuffer(s)) s = s.toString('latin1');
  // python base58 b58decode strips? -> it does v.rstrip? Actually scrub_input
  let nPad = 0;
  while (nPad < s.length && s[nPad] === '1') nPad++;
  let n = 0n;
  for (const ch of s) {
    const idx = ALPHA.indexOf(ch);
    if (idx < 0) throw new Error('bad char ' + ch);
    n = n * 58n + BigInt(idx);
  }
  const bytes = [];
  while (n > 0n) { bytes.unshift(Number(n % 256n)); n = n / 256n; }
  return Buffer.concat([Buffer.alloc(nPad), Buffer.from(bytes)]);
}

function sha256(b) { return crypto.createHash('sha256').update(b).digest(); }

function b58encode_check(buf) {
  const dig = sha256(sha256(buf));
  return b58encode2(Buffer.concat([buf, dig.slice(0, 4)]));
}

function b58encode_int(i) {
  if (i === 0) return '1';   // python: default_one -> '1'
  let n = BigInt(i);
  let out = '';
  while (n > 0n) { out = ALPHA[Number(n % 58n)] + out; n = n / 58n; }
  return out;
}

module.exports = { b58encode: b58encode2, b58decode, b58encode_check, b58encode_int, sha256, ALPHA };

if (require.main === module) {
  const mode = process.argv[2];
  const arg = process.argv[3];
  if (mode === 'check') {
    // arg is hex of payload
    console.log(b58encode_check(Buffer.from(arg, 'hex')));
  } else if (mode === 'checklen') {
    console.log(b58encode_check(Buffer.from(arg, 'hex')).length);
  } else if (mode === 'enc') {
    console.log(b58encode2(Buffer.from(arg, 'hex')));
  } else if (mode === 'dec') {
    console.log(b58decode(arg).toString('hex'));
  } else if (mode === 'checkdec') {
    // arg is b58 string -> hex payload
    const raw = b58decode(arg);
    console.log(raw.slice(0, raw.length - 4).toString('hex'));
  }
}

